1	export interface Scenario {
2	  customer: { yearsWithMHPCO: number };
3	  steps: Step[];
4	}
5	
6	export interface Step {
7	  op: string;
8	  items?: unknown[];
9	  policy?: number;
10	  incident?: unknown;
11	}
12	
13	export interface QuoteResult {
14	  premium: number;
15	}
16	
17	export interface ScenarioResults {
18	  results: QuoteResult[];
19	}
20	
21	const BASE_PREMIUMS: Record<string, number> = {
22	  sword: 100,
23	  amulet: 60,
24	  staff: 80,
25	};
26	
27	const PROCESSING_FEE = 5;
28	
29	/**
30	 * The first-insurance surcharge is +10%, applied as the exact ratio 11/10
31	 * rather than a 1.1 multiplier. Floating-point `100 * 1.1` is
32	 * 110.00000000000001, which rounds up to 111 and yields a 116 G premium
33	 * instead of 115 G. Multiplying before dividing keeps the arithmetic exact.
34	 */
35	const FIRST_INSURANCE_NUMERATOR = 11;
36	const FIRST_INSURANCE_DENOMINATOR = 10;
37	
38	const applyFirstInsuranceSurcharge = (amount: number): number =>
39	  (amount * FIRST_INSURANCE_NUMERATOR) / FIRST_INSURANCE_DENOMINATOR;
40	
41	/** All rounding is in the MHPCO's favor — always up. */
42	const roundInMHPCOsFavor = Math.ceil;
43	
44	interface InsuredItem {
45	  type: string;
46	}
47	
48	const sumBasePremiums = (items: InsuredItem[]): number =>
49	  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
50	
51	const quotePremium = (step: Step): QuoteResult => {
52	  const base = sumBasePremiums((step.items ?? []) as InsuredItem[]);
53	
54	  return {
55	    premium: roundInMHPCOsFavor(applyFirstInsuranceSurcharge(base)) +
56	      PROCESSING_FEE,
57	  };
58	};
59	
60	export const runScenario = (scenario: Scenario): ScenarioResults => ({
61	  results: scenario.steps.map(quotePremium),
62	});
63

