51	      customer: { yearsWithMHPCO: 0 },
52	      steps: [
53	        {
54	          op: "quote",
55	          items: [
56	            { type: "staff", material: "oak", enchantment: 1, cursed: false },
57	          ],
58	        },
59	      ],
60	    });
61	
62	    expect(result).toEqual({ results: [{ premium: 93 }] });
63	  });
