77	  it.todo("adds a 30% risk surcharge for a highly enchanted item (enchantment >= 5) — sword at 5 = 130 G");
78	  it.todo("does not add the enchantment surcharge below level 5 — sword at 4 = 100 G");
79	  it.todo("adds both surcharges for a cursed and highly enchanted item — sword = 180 G");
80	
