82	  it.todo("gives a 20% loyalty discount for a customer with >= 2 years — sword = 80 G");
83	  it.todo("gives no loyalty discount below 2 years with MHPCO — sword = 100 G");
84	  it.todo("adds a 10% initial assessment surcharge on the first insurance — sword = 110 G");
85	  it.todo("gives a 15% discount on each contract after the first — second quote of a sword = 85 G");
86	
