96	  it.todo("pays nothing when the damage does not exceed the deductible — 100 G damage pays 0 G");
97	  it.todo("applies the deductible once per incident, not per damaged item");
98	  it.todo("reports the remaining cap after a claim — twice the insurance sum minus payout");
99	
